import{_ as a,o as n,c as i,a4 as t}from"./chunks/framework.DzJZdBQK.js";const x=JSON.parse('{"title":"cli-tool - 命令行工具","description":"","frontmatter":{"date":"2019-04-16T15:00","title":"cli-tool - 命令行工具","categories":["hbase","hbase indexer"],"tags":["hbase","hbase indexer"]},"headers":[{"level":2,"title":"add-indexer","slug":"add-indexer","link":"#add-indexer","children":[]},{"level":2,"title":"update-indexer","slug":"update-indexer","link":"#update-indexer","children":[]},{"level":2,"title":"list-indexers","slug":"list-indexers","link":"#list-indexers","children":[]},{"level":2,"title":"delete-indexer","slug":"delete-indexer","link":"#delete-indexer","children":[]}],"relativePath":"posts/bigdata/hbase-indexer/cli-tool.md","filePath":"posts/bigdata/hbase-indexer/cli-tool.md"}'),d={name:"posts/bigdata/hbase-indexer/cli-tool.md"};function s(o,e,l,r,p,h){return n(),i("div",null,[...e[0]||(e[0]=[t(`<p>The HBase Indexer includes a number of command line tools for adding, updating, listing, and deleting indexers. All of these tools are executed by supplying a command name to the hbase-indexer tool. For example, to use the list-indexers command, you would enter the following:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./bin/hbase-indexer list-indexers</span></span></code></pre></div><p>Running any of the commands below with the --help parameter will show a listing of possible command parameters.</p><h2 id="add-indexer" tabindex="-1">add-indexer <a class="header-anchor" href="#add-indexer" aria-label="Permalink to &quot;add-indexer&quot;">​</a></h2><p>The &quot;add-indexer&quot; command is used for configuring a new indexer.</p><p>When adding an indexer, you need to supply at least the following:</p><ul><li>the name of the indexer</li><li>the indexer&#39;s definition (in the form of an xml file)</li><li>connection information to the ZooKeeper used by Solr</li></ul><p>In order to add a basic indexer named &quot;myindexer&quot; whose definition is saved in a file called myindexer.xml, with ZooKeeper running on a server named myzkhost:2181/solr and a Solr collection named mycollection, you would execute the following:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./bin/hbase-indexer add-indexer \\</span></span>
<span class="line"><span>                      --name myindexer \\</span></span>
<span class="line"><span>                      --indexer-conf myindexer.xml \\</span></span>
<span class="line"><span>                      --cp solr.zk=myzkhost:2181/solr \\</span></span>
<span class="line"><span>                      --cp solr.collection=mycollection</span></span></code></pre></div><h2 id="update-indexer" tabindex="-1">update-indexer <a class="header-anchor" href="#update-indexer" aria-label="Permalink to &quot;update-indexer&quot;">​</a></h2><p>The update-indexer command is used for updating the definition or the state of an indexer.</p><p>This command is most typically used for updating the definition of an indexer -- for example, changing the list of fields to be indexed.</p><p>The parameters to the update-indexer tool are generally the same as those for the add-indexer tool, but none of them are mandatory except for the name field.</p><p>To update the definition of the indexer that was created in the example for add-indexer, you would run the following:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./bin/hbase-indexer update-indexer --name myindexer --indexer-conf myupdatedindexer.xml</span></span></code></pre></div><p>Any parameters (other than the name parameter) that you supply to the update-indexer command will overwrite existing parameters for the indexer.</p><h2 id="list-indexers" tabindex="-1">list-indexers <a class="header-anchor" href="#list-indexers" aria-label="Permalink to &quot;list-indexers&quot;">​</a></h2><p>The list-indexer command lists all currently configured indexers, including various status information about them.</p><p>This command can be run without any additional parameters.</p><h2 id="delete-indexer" tabindex="-1">delete-indexer <a class="header-anchor" href="#delete-indexer" aria-label="Permalink to &quot;delete-indexer&quot;">​</a></h2><p>The delete-indexer command removes an indexer and stops all indexing processes for that indexer.</p><p>The --name parameter is mandatory for this command.</p>`,22)])])}const m=a(d,[["render",s]]);export{x as __pageData,m as default};
